/* =====================================================================
   Small reusable hook: reveals an element with a class once it
   scrolls into view (fade-up / slide-left / slide-right handled by CSS).
   ===================================================================== */
function useReveal(ref) {
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          el.classList.add("in-view");
          io.unobserve(el);
        }
      },
      { threshold: 0.15, rootMargin: "0px 0px -60px 0px" }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [ref]);
}

const Reveal = ({ as: Tag = "div", variant = "up", className = "", children, ...rest }) => {
  const ref = useRef(null);
  useReveal(ref);
  return (
    <Tag ref={ref} className={`sm-reveal sm-reveal-${variant} ${className}`} {...rest}>
      {children}
    </Tag>
  );
};

/* =====================================================================
   Animated skill bar — animates width only once it enters the viewport.
   ===================================================================== */
const SkillBar = ({ label, level, tag }) => {
  const ref = useRef(null);
  const [w, setW] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setW(level);
          io.unobserve(el);
        }
      },
      { threshold: 0.4 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [level]);
  return (
    <div className="sm-bar-row" ref={ref}>
      <div className="sm-bar-label"><span>{label}</span><span>{tag}</span></div>
      <div className="sm-bar-track"><div className="sm-bar-fill" style={{ width: `${w}%` }} /></div>
    </div>
  );
};

/* =====================================================================
   Particle network canvas — ambient background behind the hero.
   ===================================================================== */
const ParticleCanvas = () => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const parent = canvas.parentElement;
    let particles = [];
    let raf;
    const COUNT = 46;
    const LINK_DIST = 130;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    function resize() {
      canvas.width = parent.offsetWidth;
      canvas.height = parent.offsetHeight;
    }
    function seed() {
      particles = Array.from({ length: COUNT }, () => ({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        vx: (Math.random() - 0.5) * 0.3,
        vy: (Math.random() - 0.5) * 0.3,
      }));
    }
    function step() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particles.forEach((p) => {
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0 || p.x > canvas.width) p.vx *= -1;
        if (p.y < 0 || p.y > canvas.height) p.vy *= -1;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 1.6, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(91,140,255,0.55)";
        ctx.fill();
      });
      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const dx = particles[i].x - particles[j].x;
          const dy = particles[i].y - particles[j].y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < LINK_DIST) {
            ctx.beginPath();
            ctx.moveTo(particles[i].x, particles[i].y);
            ctx.lineTo(particles[j].x, particles[j].y);
            ctx.strokeStyle = `rgba(91,140,255,${0.14 * (1 - dist / LINK_DIST)})`;
            ctx.lineWidth = 1;
            ctx.stroke();
          }
        }
      }
      raf = requestAnimationFrame(step);
    }

    resize(); seed();
    if (!reduced) step(); else { ctx.clearRect(0,0,canvas.width,canvas.height); }
    const onResize = () => { resize(); seed(); };
    window.addEventListener("resize", onResize);
    return () => { window.removeEventListener("resize", onResize); cancelAnimationFrame(raf); };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{ position: "absolute", inset: 0, zIndex: 0, opacity: 0.6 }}
    />
  );
};

/* =====================================================================
   Custom glowing cursor with a trailing ring (desktop / fine pointer only)
   ===================================================================== */
const CustomCursor = () => {
  const dotRef = useRef(null);
  const ringRef = useRef(null);
  const glowRef = useRef(null);

  useEffect(() => {
    if (window.matchMedia("(hover:none)").matches) return;
    let tx = 0, ty = 0, rx = 0, ry = 0, raf;

    const onMove = (e) => {
      tx = e.clientX; ty = e.clientY;
      if (dotRef.current) { dotRef.current.style.left = tx + "px"; dotRef.current.style.top = ty + "px"; }
      if (glowRef.current) { glowRef.current.style.left = tx + "px"; glowRef.current.style.top = ty + "px"; }
    };
    const animate = () => {
      rx += (tx - rx) * 0.16;
      ry += (ty - ry) * 0.16;
      if (ringRef.current) { ringRef.current.style.left = rx + "px"; ringRef.current.style.top = ry + "px"; }
      raf = requestAnimationFrame(animate);
    };
    window.addEventListener("mousemove", onMove);
    animate();

    const interactive = document.querySelectorAll("a, button, .sm-card");
    const enter = () => ringRef.current && ringRef.current.classList.add("active");
    const leave = () => ringRef.current && ringRef.current.classList.remove("active");
    interactive.forEach((el) => { el.addEventListener("mouseenter", enter); el.addEventListener("mouseleave", leave); });

    return () => {
      window.removeEventListener("mousemove", onMove);
      cancelAnimationFrame(raf);
      interactive.forEach((el) => { el.removeEventListener("mouseenter", enter); el.removeEventListener("mouseleave", leave); });
    };
  }, []);

  return (
    <>
      <div className="sm-cursor" ref={glowRef} />
      <div className="sm-cursor-dot" ref={dotRef} />
      <div className="sm-cursor-ring" ref={ringRef} />
    </>
  );
};

